import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { addToCart } from '../redux/slices/cartSlice';
import axios from 'axios';

const ProductDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [product, setProduct] = useState({});
  const [qty, setQty] = useState(1);
  const [loading, setLoading] = useState(true);
  const dispatch = useDispatch();

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const { data } = await axios.get(`/api/v1/products/${id}`);
        setProduct(data);
        setLoading(false);
      } catch (error) {
        // Fallback for placeholder products when DB is empty
        let found = null;

        // Check if ID is a mock ID (e.g. 'electronics-1000')
        if (id.includes('-')) {
          const lastDashIndex = id.lastIndexOf('-');
          const category = id.substring(0, lastDashIndex);
          const mockProducts = await import('../data/mockData').then(m => m.getMockProductsByCategory(category));
          found = mockProducts.find(p => p._id === id);
        } else {
          // Check standard hardcoded placeholders from Home
          const placeholders = [
            { _id: '1', name: 'Fashion Trends Premium Fashion', image: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQgqyNOUQu6LS3UxShAAlosUERIk1M3aZpr8Q&s', brand: 'Secrets', rating: 4.8, numReviews: 124, price: 299.99 },
            { _id: '2', name: 'Smart Fitness Watch Series 7', image: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTlg5O1-AfzeM6xhKR6dBmnlhtqaPqmQo3nMg&s', brand: 'Apple', rating: 4.9, numReviews: 320, price: 399.99 },
            { _id: '3', name: 'Professional Laptop', image: 'https://5.imimg.com/data5/YQ/FP/MY-64579269/lenovo-laptop-500x500.png', brand: 'Lenovo', rating: 4.7, numReviews: 89, price: 1299.99 },
            { _id: '4', name: 'Noise Cancelling Earbuds', image: 'data:image/webp;base64,', brand: 'Bose', rating: 4.6, numReviews: 210, price: 199.99 },
            {
              _id: '5', name: 'Premium Cloth', image: 'data:image/jpeg;base64,', brand: 'All', rating: 4.8, numReviews: 124, price: 299.99
            },
            { _id: '6', name: 'premium kitchen accessories', image: 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQcI33flpp7G4a_lGjYdmAOR42P3W9FK8uq4w&s', brand: 'all', rating: 4.9, numReviews: 320, price: 399.99 },
            { _id: '7', name: 'Professional DSLR Camera', image: 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?w=500&q=80', brand: 'Canon', rating: 4.7, numReviews: 89, price: 1299.99 },
            { _id: '8', name: 'Toy accessories', image: 'data:image/jpeg;base64,', brand: 'Bose', rating: 4.6, numReviews: 210, price: 199.99 },
            { _id: '9', name: 'hand mead accessories', image: 'data:image/jpeg;base64,', brand: '', rating: 4.8, numReviews: 124, price: 299.99 },
            { _id: '10', name: 'Bodyfit Gym Kit Combo', image: 'https://encrypted-tbn1.gstatic.com/shopping?q=tbn:ANd9GcTkTK8tVk3ssEe0G6zuxZe2NRUyhWZA69mWJOroIdM24IK-_QgjYf43haUtozCrrKgbWi7dC6_w4IuY41OidiipgBxGkU0d4AwKO-sLHMbHAhRxZmr6SQeAkQ', brand: '', rating: 4.9, numReviews: 320, price: 399.99 },
            { _id: '11', name: 'SONGESAND Bedroom Furniture Set of 5', image: 'https://encrypted-tbn1.gstatic.com/shopping?q=tbn:ANd9GcTuZRMSRoWkkQj_OoOEjcBPeICXpkDQiPjVibYn9UtL6G6bXPjnuL9iyFgPkMjmH8uwHMTWkj6nGM1XPrqm5BbCXk1vsIsso8kWHHy1yROlE38N6xaYsKpR-w', brand: 'Canon', rating: 4.7, numReviews: 89, price: 1299.99 },
            { _id: '12', name: 'Home Decor', image: 'https://encrypted-tbn1.gstatic.com/shopping?q=tbn:ANd9GcS4MVAhM7QTEIhABKMF-MqHpcxTG00keYHyZkdJOWFenEp6fvpUDeNP6hclgsSFYtS4oPIGv5Y8B0IZZ4iUHKh16C0QJkD5aMnwQPtIGDqV', brand: 'Bose', rating: 4.6, numReviews: 210, price: 199.99 },
            { _id: '13', name: 'Sports Premium Shoes', image: 'https://encrypted-tbn3.gstatic.com/shopping?q=tbn:ANd9GcSIj0hzMm2r573zI3-5eoLB4ZNtrDO69P1DKcFEx1XR6De4hTuvsn6zjbRDe3Fo9kKOZmTDoW_RXr-UOCzzLFLp3VewmXPVNhh1Tc6ikOYcWxbca_1QMQOVPw', brand: 'Puma', rating: 4.8, numReviews: 124, price: 299.99 },
            { _id: '14', name: 'deals on festive gift', image: 'https://encrypted-tbn0.gstatic.com/shopping?q=tbn:ANd9GcRGz-YLETAhvlzHgJxBw2O5AxnTiy9aN2nwHlsTpp5i8e5rGokajnMbtk5Lt_SF8XbuZuElWuMtPibLZ6Prs3nO2qAt12_-', brand: '', rating: 4.9, numReviews: 320, price: 399.99 },
            { _id: '15', name: 'dry fruits combo', image: 'https://encrypted-tbn0.gstatic.com/shopping?q=tbn:ANd9GcT2Gqv-8UoEnWHcweCojgHiIKo7SKwSuQrbqE4-xwe7i-umyxVptASnCxL-nzAdrSSeDbzsSxNR2OsF0qzSz1KDYzUjDUEqOQ', brand: 'Healthy', rating: 4.7, numReviews: 89, price: 1299.99 },
          ];
          found = placeholders.find(p => p._id === id);
        }

        if (found) {
          setProduct(found);
        } else {
          setProduct(null);
        }
        setLoading(false);
      }
    };
    fetchProduct();
  }, [id]);

  const addToCartHandler = () => {
    dispatch(addToCart({ ...product, qty }));
    navigate('/cart');
  };

  if (loading) return <div className="container" style={{ padding: '5rem 0', textAlign: 'center' }}><h2>Loading Product Details...</h2></div>;
  if (!product) return <div className="container" style={{ padding: '5rem 0', textAlign: 'center' }}><h2>Product Not Found!</h2></div>;

  return (
    <div className="container" style={{ padding: '2rem 0' }}>
      <Link to="/" style={styles.backBtn}>&larr; Back to Catalog</Link>

      <div style={styles.grid}>
        <div style={styles.imageCol}>
          <img src={product.image} alt={product.name} style={styles.image} className="glass" />
        </div>

        <div style={styles.infoCol}>
          <p style={styles.brand}>{product.brand}</p>
          <h1 style={styles.title}>{product.name}</h1>
          <div style={styles.rating}>⭐ {product.rating} ({product.numReviews} Reviews)</div>
          <p style={styles.price}>${product.price}</p>
          <p style={styles.description}>{product.description}</p>
        </div>

        <div style={styles.actionCol}>
          <div className="glass" style={styles.actionCard}>
            <div style={styles.actionRow}>
              <span>Price:</span>
              <strong>${product.price}</strong>
            </div>
            <div style={styles.actionRow}>
              <span>Status:</span>
              <strong>{product.countInStock > 0 ? 'In Stock' : 'Out of Stock'}</strong>
            </div>

            {product.countInStock > 0 && (
              <div style={styles.actionRow}>
                <span>Qty:</span>
                <select value={qty} onChange={(e) => setQty(Number(e.target.value))} style={styles.select}>
                  {[...Array(product.countInStock).keys()].map((x) => (
                    <option key={x + 1} value={x + 1}>{x + 1}</option>
                  ))}
                </select>
              </div>
            )}

            <button
              style={{ ...styles.addBtn, opacity: product.countInStock === 0 ? 0.5 : 1 }}
              disabled={product.countInStock === 0}
              onClick={addToCartHandler}
            >
              Add To Cart
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

const styles = {
  backBtn: {
    display: 'inline-block',
    marginBottom: '2rem',
    color: 'var(--text-secondary)',
    fontWeight: 'bold',
  },
  grid: {
    display: 'grid',
    gridTemplateColumns: '1fr',
    gap: '3rem',
  },
  '@media (min-width: 768px)': {
    grid: {
      gridTemplateColumns: '1fr 1fr 300px',
    }
  },
  imageCol: {
    width: '100%',
  },
  image: {
    width: '100%',
    borderRadius: '12px',
    objectFit: 'cover',
  },
  infoCol: {
    display: 'flex',
    flexDirection: 'column',
  },
  brand: {
    color: 'var(--accent-color)',
    fontWeight: 'bold',
    letterSpacing: '2px',
    textTransform: 'uppercase',
  },
  title: {
    fontSize: '2.5rem',
    margin: '0.5rem 0',
    lineHeight: '1.2',
  },
  rating: {
    color: '#fbbf24',
    marginBottom: '1rem',
    fontSize: '1.1rem',
  },
  price: {
    fontSize: '2rem',
    fontWeight: '800',
    marginBottom: '1.5rem',
  },
  description: {
    color: 'var(--text-secondary)',
    fontSize: '1.1rem',
    lineHeight: '1.8',
  },
  actionCard: {
    padding: '1.5rem',
    borderRadius: '12px',
  },
  actionRow: {
    display: 'flex',
    justifyContent: 'space-between',
    paddingBottom: '1rem',
    marginBottom: '1rem',
    borderBottom: '1px solid rgba(255,255,255,0.1)',
  },
  select: {
    padding: '0.3rem 0.8rem',
    borderRadius: '6px',
    backgroundColor: 'var(--bg-primary)',
    color: 'white',
    border: '1px solid var(--border-color)',
  },
  addBtn: {
    width: '100%',
    padding: '1rem',
    fontSize: '1.1rem',
    borderRadius: '8px',
    marginTop: '1rem',
  }
};

const responsiveStyle = document.createElement('style');
responsiveStyle.innerHTML = `
  @media (min-width: 992px) {
    .container > div:nth-child(2) {
      grid-template-columns: 2fr 2fr 1fr !important;
    }
  }
`;
document.head.appendChild(responsiveStyle);

export default ProductDetail;
